P=lambda n,p:{'nazev':n,'popis':p}
def d(slug, ident, sablonaSlug, nazev, nazevA, popis, kat, il, slova, title, desc, perex, obsahPopis, obsah, online, hodi, nehodi, po, faq, zakony, vt, vd):
    landing={'title':title,'description':desc,'perex':perex,'obsahPopis':obsahPopis,'obsah':[P(*x) for x in obsah],'kroky':[P(*x) for x in K3],'online':online,'hodiSe':hodi,'nehodiSe':nehodi,'po':[P(*x) for x in po],'faq':[{'q':q,'a':a} for q,a in faq+[PRIV]],'zakony':zakony,'souvisejiciPopis':'Alte documente, tot gratuite.'}
    if not 70<=len(desc)<=170: print('DESC',slug,len(desc))
    if len(title.replace('{rok}','2026'))>70: print('TITLE',slug,len(title.replace('{rok}','2026')))
    for w in ('model','PDF','gratuit'):
        assert w in (title+' '+desc).lower() or w=='PDF' and 'PDF' in title+desc, (slug,w)
    zapis(O+slug+'.ts','ro',sablonaSlug,ident,nazev,nazevA,{'popis':popis,'kategorie':kat,'ilustrace':il,'slova':slova},kat,landing,{'title':vt,'description':vd,'podnadpis':'Gratuit · rezultat în PDF și Word · durează câteva minute'})
